tool_input.old_string:
.title {
  display: inline-block;
  font-size: 18px;
  font-weight: 600;
  line-height: 22px;
  color: var(--menu-text-color, white);
  white-space: nowrap;
  cursor: default;
  vertical-align: top;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}

tool_input.new_string:
.title {
  display: inline-block;
  font-size: 16px;
  font-weight: 600;
  line-height: 20px;
  color: var(--menu-text-color, white);
  white-space: nowrap;
  cursor: default;
  vertical-align: top;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}
